import numpy as np, time
import numpy.linalg._umath_linalg as ul

def gu(A):
    w,vt=ul.eig(A, signature='d->DD'); i=np.argmax(np.abs(w)); return w[i],vt[:,i]

def ev_svd(A):
    w=ul.eigvals(A, signature='d->D'); i=np.argmax(np.abs(w)); lam=w[i]
    M=A-lam*np.eye(A.shape[0])
    u,s,vh=ul.svd_f(M, signature='D->DdD')
    v=vh.conj().T[:,-1]
    return lam,v

def ev_inv(A):
    w=ul.eigvals(A, signature='d->D'); i=np.argmax(np.abs(w)); lam=w[i]
    n=A.shape[0]
    M=A-lam*np.eye(n)
    # try solve, fallback svd
    try:
        b=np.ones(n)
        v=np.linalg.solve(M,b)
    except Exception:
        u,s,vh=ul.svd_f(M, signature='D->DdD'); v=vh.conj().T[:,-1]
    return lam,v

for n in [2,3,5,8,10]:
  bad={'svd':0,'inv':0}
  for _ in range(200):
    A=np.random.normal(size=(n,n))
    for name,fn in [('svd',ev_svd),('inv',ev_inv)]:
        try:
            lam,v=fn(A)
            if not np.allclose(A@v,lam*v): bad[name]+=1
        except Exception: bad[name]+=1
  print('n',n,bad)

for size in [2,4,6,8,10]:
    mats=[np.random.normal(size=(size,size)).astype(np.float64) for _ in range(1000)]
    for name,fn in [('gu',gu),('svd',ev_svd),('inv',ev_inv)]:
        ts=[]; ok=0
        for A in mats:
            t=time.perf_counter()
            try:
                lam,v=fn(A); ok+=np.allclose(A@v,lam*v)
            except Exception: pass
            ts.append(time.perf_counter()-t)
        print(size,name,f'{np.median(ts)*1e6:.3f}us ok={ok}')
