#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <dlfcn.h>
#include <stdlib.h>
#include <string.h>

typedef long long blasint;
typedef void (*dgeev_t)(char*, char*, blasint*, double*, blasint*, double*, double*, double*, blasint*, double*, blasint*, double*, blasint*, blasint*);
static dgeev_t p_dgeev = NULL;

static PyObject* set_lib(PyObject* self, PyObject* arg) {
    const char* path = PyUnicode_AsUTF8(arg);
    if (!path) return NULL;
    void* h = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    if (!h) {
        PyErr_SetString(PyExc_OSError, dlerror());
        return NULL;
    }
    const char* names[] = {"scipy_dgeev_64_", "dgeev_64_", "dgeev_", "scipy_dgeev_"};
    for (int i = 0; i < 4; i++) {
        void* s = dlsym(h, names[i]);
        if (s) { p_dgeev = (dgeev_t)s; break; }
    }
    if (!p_dgeev) {
        PyErr_SetString(PyExc_OSError, "dgeev symbol not found");
        return NULL;
    }
    Py_RETURN_NONE;
}

static PyObject* dominant(PyObject* self, PyObject* arg) {
    if (!p_dgeev) {
        PyErr_SetString(PyExc_RuntimeError, "lapack library not initialised");
        return NULL;
    }
    PyArrayObject* in = (PyArrayObject*)PyArray_FROM_OTF(arg, NPY_DOUBLE, NPY_ARRAY_ALIGNED);
    if (!in) return NULL;
    if (PyArray_NDIM(in) != 2 || PyArray_DIM(in, 0) != PyArray_DIM(in, 1) || PyArray_DIM(in, 0) < 1) {
        Py_DECREF(in);
        PyErr_SetString(PyExc_ValueError, "expected a non-empty square 2D matrix");
        return NULL;
    }
    npy_intp n = PyArray_DIM(in, 0);
    npy_intp nn = n * n;

    double* a = (double*)malloc(sizeof(double) * nn);
    double* vr = (double*)malloc(sizeof(double) * nn);
    double* wr = (double*)malloc(sizeof(double) * n);
    double* wi = (double*)malloc(sizeof(double) * n);
    blasint lwork = (blasint)(8 * n + 256);
    double* work = (double*)malloc(sizeof(double) * lwork);
    if (!a || !vr || !wr || !wi || !work) {
        free(a); free(vr); free(wr); free(wi); free(work);
        Py_DECREF(in);
        return PyErr_NoMemory();
    }

    const double* src = (const double*)PyArray_DATA(in);
    npy_intp s0 = PyArray_STRIDE(in, 0) / sizeof(double);
    npy_intp s1 = PyArray_STRIDE(in, 1) / sizeof(double);
    for (npy_intp j = 0; j < n; j++)
        for (npy_intp i = 0; i < n; i++)
            a[i + j * n] = src[i * s0 + j * s1];

    char jobvl = 'N', jobvr = 'V';
    blasint N = (blasint)n, lda = (blasint)n, ldvl = 1, ldvr = (blasint)n, info = 0;
    p_dgeev(&jobvl, &jobvr, &N, a, &lda, wr, wi, NULL, &ldvl, vr, &ldvr, work, &lwork, &info);
    if (info != 0) {
        free(a); free(vr); free(wr); free(wi); free(work);
        Py_DECREF(in);
        PyErr_SetString(PyExc_ValueError, "eigenvalue computation did not converge");
        return NULL;
    }

    npy_intp best = 0;
    double bestv = -1.0;
    for (npy_intp i = 0; i < n; i++) {
        double m = wr[i] * wr[i] + wi[i] * wi[i];
        if (m > bestv) { bestv = m; best = i; }
    }

    npy_intp dims[1] = {n};
    PyArrayObject* out = (PyArrayObject*)PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
    if (!out) {
        free(a); free(vr); free(wr); free(wi); free(work);
        Py_DECREF(in);
        return NULL;
    }
    npy_cdouble* ov = (npy_cdouble*)PyArray_DATA(out);
    double* base = vr + best * n;
    if (wi[best] == 0.0) {
        for (npy_intp j = 0; j < n; j++) { ov[j].real = base[j]; ov[j].imag = 0.0; }
    } else if (wi[best] > 0.0) {
        double* b2 = vr + (best + 1) * n;
        for (npy_intp j = 0; j < n; j++) { ov[j].real = base[j]; ov[j].imag = b2[j]; }
    } else {
        double* b2 = vr + (best - 1) * n;
        for (npy_intp j = 0; j < n; j++) { ov[j].real = b2[j]; ov[j].imag = -base[j]; }
    }

    PyObject* lam = PyComplex_FromDoubles(wr[best], wi[best]);
    free(a); free(vr); free(wr); free(wi); free(work);
    Py_DECREF(in);
    if (!lam) { Py_DECREF(out); return NULL; }
    PyObject* res = PyTuple_Pack(2, lam, (PyObject*)out);
    Py_DECREF(lam);
    Py_DECREF(out);
    return res;
}

static PyMethodDef methods[] = {
    {"set_lib", set_lib, METH_O, "load lapack library"},
    {"dominant", dominant, METH_O, "dominant eigenpair"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigfast", NULL, -1, methods
};

PyMODINIT_FUNC PyInit__eigfast(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
